use crate::{domain::wallet::{WalletStats, WalletTradeObservation, WalletTier}, smart_money::{score_wallet, SmartMoneyThresholds}}; use std::collections::HashMap;
#[derive(Default)] pub struct WalletTracker { wallets: HashMap<String, WalletStats>, observations: Vec<WalletTradeObservation>, thresholds: SmartMoneyThresholds }
impl WalletTracker { pub fn new(thresholds: SmartMoneyThresholds) -> Self { Self { thresholds, ..Self::default() } } pub fn upsert(&mut self, mut stats: WalletStats) { score_wallet(&mut stats, &self.thresholds); self.wallets.insert(stats.wallet.clone(), stats); } pub fn observe(&mut self, observation: WalletTradeObservation) { self.observations.push(observation); } pub fn qualified_consensus(&self, mint: &str) -> Vec<&WalletStats> { self.observations.iter().filter(|o| o.mint == mint && matches!(o.side, crate::domain::wallet::Side::Buy)).filter_map(|o| self.wallets.get(&o.wallet)).filter(|w| matches!(w.tier, WalletTier::Qualified | WalletTier::HighConfidence)).collect() } }
